mapper.sql:
WHERE a.achievement_type = 'employment-rate-improvements'
  AND a.deleted_yn = 'N'

    AND a.management_no = #{criteria.managementNo}


    AND a.management_item_code = #{criteria.managementItemCode}


    AND a.achievement_status = #{criteria.achievementStatus}


    AND a.evaluation_year = #{criteria.evaluationYear}

AND (FALSE

    OR TRUE


    OR a.teacher_user_id = #{userId}


    OR EXISTS (
        SELECT 1
        FROM organization_user_mappings r
        JOIN organization_user_mappings t ON t.organization_code = r.organization_code
        WHERE r.user_id = #{userId}
          AND r.status = 'ACTIVE'
          AND t.user_id = a.teacher_user_id
          AND t.status = 'ACTIVE'
    )


    OR EXISTS (
        SELECT 1
        FROM evaluation_organization_mappings r
        JOIN organization_user_mappings t ON t.organization_code = r.organization_code
        WHERE r.user_id = #{userId}
          AND r.business_type = 'FACULTY_ACHIEVEMENT'
          AND r.data_scope IN ('DEPARTMENT', 'COLLEGE', 'BUSINESS', 'ALL')
          AND t.user_id = a.teacher_user_id
          AND t.status = 'ACTIVE'
    )

)

mapper.select:
SELECT 


ORDER BY a.achievement_date DESC, a.achievement_id DESC
LIMIT #{criteria.pageSize}
OFFSET #{criteria.rowOffset}

SELECT f.target_user_id
FROM evaluation_finalizations f
WHERE f.target_user_id = #{userId}
  AND f.evaluation_year = #{year}
  AND f.final_status = 'EVALUATION_CONFIRMED'
FOR UPDATE

mapper.insert:
INSERT INTO education_achievements (
    management_no, achievement_type, teacher_user_id, organization_code,
    evaluation_year, management_item_code, achievement_date, attachment_ids,
    created_by, updated_by, request_id
)
VALUES (
    #{managementNo}, 'employment-rate-improvements', #{teacherUserId}, #{organizationCode},
    #{evaluationYear}, #{managementItemCode}, #{achievementDate}, CAST(#{attachmentJson} AS jsonb),
    #{userId}, #{userId}, #{requestId}
)

INSERT INTO employment_rate_improvement_achievement_details (
    achievement_id, special_lecture_start_date, special_lecture_end_date, mock_exam_question_period
)
VALUES (
    #{id}, #{body.specialLectureStartDate}, #{body.specialLectureEndDate}, #{body.mockExamQuestionPeriod}
)

mapper.update:
UPDATE employment_rate_improvement_achievement_details
SET special_lecture_start_date = #{body.specialLectureStartDate},
    special_lecture_end_date = #{body.specialLectureEndDate},
    mock_exam_question_period = #{body.mockExamQuestionPeriod}
WHERE achievement_id = #{id}

mapper.insert:
INSERT INTO education_achievement_status_histories (
    achievement_type, achievement_id, next_status, action_type, processed_by, opinion, request_id
)
VALUES (
    'employment-rate-improvements', #{id}, 'DRAFT', 'CREATE', #{userId}, '최초 입력', #{requestId}
)

INSERT INTO data_change_histories (
    target_business, target_key, change_type, field_name, before_value, after_value,
    changed_by, change_reason, request_id
)
VALUES (
    'education_achievements', CAST(#{id} AS text), #{type}, 'snapshot', #{before}, #{after},
    #{userId}, '취업률 제고 실적 저장', #{requestId}
)
